var i=6;var n=`006-weights-volumes-and-unit-conversions`;var s=`001`;var a={en:`Weights, Volumes, and Unit Conversions`,ua:`Вага, об’єм та перетворення одиниць вимірювання`};var o={short:`Measuring by weight, volume, and temperature requires understanding different units and the difference between accurate and repeatable measurements. Consistent conversions and properly used equipment make recipes reproducible, especially in baking and food safety.`,sections:[{title:`Core idea`,text:`Grams and kilograms describe mass; milliliters and liters describe volume. The relation between mass and volume depends on density, so 100 ml of oil does not weigh exactly 100 g, and a cup of flour is not equivalent to a cup of water by mass.`},{title:`Scientific / practical principles`,text:`Useful exact metric conversions are 1 kg = 1,000 g and 1 L = 1,000 ml. Fahrenheit converts to Celsius by subtracting 32 and multiplying by 5/9; Celsius converts to Fahrenheit by multiplying by 9/5 and adding 32.`},{title:`How to apply it`,text:`Use a digital scale for flour, salt, sugar and other precise ingredients. Tare the container between additions, select a measuring jug for liquids, and verify which type of “cup,” tablespoon or teaspoon a source recipe assumes.`},{title:`Practical example`,text:`An oven set to 180°C is about 356°F, commonly rounded to 350°F in recipes. However, 250 ml of flour cannot be converted to grams without accounting for packing and the flour type.`},{title:`Common mistakes and limitations`,text:`The most frequent errors are using volume as mass, mixing metric and US customary cups, neglecting a tare operation, and rounding tiny quantities such as leavening agents too aggressively.`},{title:`Additional application`,text:`Accuracy means closeness to the intended measurement; precision means repeatability. A scale reading 101 g every time is precise but inaccurate if the true mass is 100 g. Calibrate equipment when needed, zero the container, and record whether measurements refer to raw or cooked food.`}]};var r={short:`Для вимірювання маси, об’єму й температури потрібні різні одиниці та розуміння похибок. Правильне перетворення величин і налаштовані інструменти допомагають відтворювати рецепти, особливо у випічці та контролі безпечності.`,sections:[{title:`Суть`,text:`Грами та кілограми вимірюють масу, а мілілітри й літри вимірюють об’єм. Зв’язок між ними залежить від густини: 100 мл олії не важать точно 100 г, а склянка борошна й склянка води мають різну масу.`},{title:`Наукові та практичні принципи`,text:`Точні метричні перетворення: 1 кг = 1 000 г, 1 л = 1 000 мл. Для перетворення Фаренгейтів на Цельсії відніміть 32 і помножте на 5/9; для зворотного перетворення помножте на 9/5 і додайте 32.`},{title:`Як застосовувати`,text:`Для борошна, солі, цукру та інших точних компонентів користуйтеся електронними вагами. Обнуляйте вагу тари між додаваннями, рідини за потреби міряйте мірним посудом і уточнюйте, яку саме «склянку» мав на увазі автор.`},{title:`Практичний приклад`,text:`Температура 180°C приблизно дорівнює 356°F; у рецептах її часто округлюють до 350°F. Натомість 250 мл борошна не можна коректно перевести в грами без знання його щільності та способу наповнення.`},{title:`Поширені помилки й обмеження`,text:`Часті помилки: прирівнювати об’єм до маси, змішувати метричні та американські міри, забувати обнулити тару та надмірно округлювати малі дози розпушувачів.`},{title:`Додаткове застосування`,text:`Точність щодо істинного значення означає близькість до потрібної величини, а повторюваність означає стабільність показників. Ваги, які завжди показують 101 г замість справжніх 100 г, повторювані, але мають похибку. За потреби перевіряйте калібрування, обнуляйте тару та уточнюйте, чи масу вказано для сирого або готового продукту.`}]};var l=[7,9,266,273];var c=`References / Джерела`;var u=[`https://www.nist.gov/pml/owm/nist-metric-recipes-sp-1290`,`https://extension.umn.edu/food/preparing/cooking-at-home`];var d={id:6,slug:n,group:`001`,title:a,en:o,ua:r,related:l,referenceTitle:c,references:u};export{d as default,o as en,s as group,i as id,c as referenceTitle,u as references,l as related,n as slug,a as title,r as ua};